-- Early rewards depend on practice, not a waiting period. Earned rewards remain owned.
begin;
update public.achievement_catalog set requirement='{"type": "sessions", "count": 1}'::jsonb, description='はじめてプレイ記録を保存する。',display_name='FIRST SIGNAL' where id='first_signal';
