update public.achievement_catalog set requirement='{"type": "combo", "value": 25, "min_sessions": 50, "repeat_count": 3}'::jsonb, description='25コンボ以上を3回。累計50プレイ。',display_name='CHAIN 25' where id='combo_20';
update public.achievement_catalog set requirement='{"type": "combo", "value": 35, "min_sessions": 75, "repeat_count": 5}'::jsonb, description='35コンボ以上を5回。累計75プレイ。',display_name='CHAIN REACTOR' where id='combo_30';
