update public.achievement_catalog set requirement='{"mode": "KEYS", "type": "mode_sessions", "count": 10}'::jsonb, description='KEYSを10回プレイする。',display_name='KEYS SPECIALIST' where id='keys_10';
update public.achievement_catalog set requirement='{"type": "any_mode", "count": 5, "modes": ["HD_TEXT", "HD_KEYS"]}'::jsonb, description='HD TEXT / HD KEYSを合計5回プレイする。',display_name='HYPER IGNITION' where id='hyper_first';
update public.achievement_catalog set requirement='{"mode": "EAR_LINK", "type": "mode_sessions", "count": 5}'::jsonb, description='EAR LINKを5回プレイする。',display_name='EAR CONTACT' where id='ear_first';
