update public.achievement_catalog set requirement='{"type": "interval_mastery", "min_seen": 30, "min_accuracy": 80}'::jsonb, description='13音程すべてに30回答以上、正答率80%以上。',display_name='INTERVAL NAVIGATOR' where id='interval_80';
