update public.achievement_catalog set requirement='{"rank": 999999, "type": "public_rank", "min_sessions": 10}'::jsonb, description='ランキングへ記録を公開する。累計10回プレイ。',display_name='OPEN CHANNEL' where id='public_record';
update public.achievement_catalog set requirement='{"rank": 10, "type": "public_rank", "min_sessions": 50}'::jsonb, description='殿堂ランキング10位以内に入る。累計50回プレイ。',display_name='TOP TEN' where id='rank_top10';
