update public.achievement_catalog set requirement='{"mode": "EAR_LINK", "type": "perfect_session", "min_answers": 15, "min_sessions": 50, "repeat_count": 3}'::jsonb, description='???',display_name='INNER EAR' where id='hidden_ear_perfect';
update public.achievement_catalog set requirement='{"type": "all_modes_perfect", "modes": ["TEXT", "KEYS", "HD_TEXT", "HD_KEYS", "EAR_LINK"], "min_answers": 20, "min_sessions": 75, "mode_min_answers": {"EAR_LINK": 10}}'::jsonb, description='???',display_name='FIVE PERFECT ORBITS' where id='hidden_all_mode_perfect';
update public.achievement_catalog set requirement='{"type": "combo", "value": 40, "min_sessions": 100, "repeat_count": 3}'::jsonb, description='???',display_name='GRAVITY CHAIN' where id='hidden_combo_50';
update public.achievement_catalog set requirement='{"ids": ["interval_90", "streak_14", "rank_first", "hidden_ear_perfect"], "type": "achievement_combo"}'::jsonb, description='???',display_name='SINGULARITY' where id='hidden_singularity';
update public.achievement_catalog set requirement='{"type": "sessions", "count": 250}'::jsonb, description='累計250回プレイする。',display_name='DEEP SPACE VOYAGER' where id='sessions_250';
update public.achievement_catalog set requirement='{"type": "sessions", "count": 500}'::jsonb, description='累計500回プレイする。',display_name='DEEP SPACE LEGEND' where id='sessions_1000';
update public.achievement_catalog set requirement='{"type": "perfect_session", "min_answers": 40, "min_sessions": 100, "repeat_count": 3}'::jsonb, description='1プレイで40問以上・全問正解を3回。累計100プレイ。',display_name='PRECISION ACE' where id='perfect_40';
update public.achievement_catalog set requirement='{"type": "combo", "value": 45, "min_sessions": 150, "repeat_count": 3}'::jsonb, description='45コンボ以上を3回。累計150プレイ。',display_name='APEX CHAIN' where id='combo_100';
update public.achievement_catalog set requirement='{"days": 7, "type": "active_days"}'::jsonb, description='通算7日プレイする。連続でなくてもよい。',display_name='SEVEN DAY JOURNEY' where id='streak_30';
update public.achievement_catalog set requirement='{"days": 15, "type": "active_days"}'::jsonb, description='通算15日プレイする。連続でなくてもよい。',display_name='FIFTEEN DAY CONSTELLATION' where id='streak_60';
update public.achievement_catalog set requirement='{"type": "all_modes_perfect", "modes": ["TEXT", "KEYS", "HD_TEXT", "HD_KEYS", "EAR_LINK"], "min_answers": 30, "min_sessions": 100, "mode_min_answers": {"EAR_LINK": 15}}'::jsonb, description='主要5モードそれぞれで30問以上・全問正解（EAR LINKは15問以上）。累計100プレイ。',display_name='FIVE STAR PRECISION' where id='all_modes_perfect_30';
update public.achievement_catalog set requirement='{"mode": "EAR_LINK", "type": "perfect_session", "min_answers": 20, "min_sessions": 75, "repeat_count": 3}'::jsonb, description='EAR LINKで20問以上・全問正解を3回。累計75プレイ。',display_name='DEEP LISTENER' where id='ear_perfect_40';
-- Immutable award amounts in historical ledgers are intentionally untouched.
update public.mode_clear_reward_catalog set reward_points=case mode when 'TEXT' then 40 when 'KEYS' then 40 when 'HD_TEXT' then 50 when 'HD_KEYS' then 50 when 'EAR_LINK' then 60 end;
update public.daily_mission_catalog set reward_points=case when reward_points<=30 then 60 else 80 end;
commit;
